userscript.function:

$share.fn={};
for(var i in $shareFnNames){
    var fnName = $shareFnNames[i];
    $share.fn[fnName] = $sObject[fnName];
}

SUX.attachEvent('onActive', function() {
    $share.fn.doQuery();
});


$share.config = config;
var type = config.TYPE;
dataOutput.setValue('TYPE', type);
var splitedType = type.split('_');
for(var i in splitedType){
    if(splitedType[i].length > 1){
        splitedType[i] = splitedType[i].charAt(0).toUpperCase()+splitedType[i].substring(1).toLowerCase();
    }else if(splitedType[i].length == 1){
        splitedType[i] = splitedType[i].toUpperCase(); 
    }
}
type = splitedType.join('');
layoutObj.cells('a').attachURL('/EmployeeContract/Progress/EmployeeContractProgressList'+type+'.sux');
setTimeout(changeHeaderText, 0, 'a', Sepoa.cache.text.get('ECT_101.TITLE_'+config.TYPE));


doServiceAjax('sepoa.svc.contract.SepoaEmployeeContractService', 'CONNECTION', 'doGetScreenConfig', null, function(so) {
    if (so.status == 1) {
        $share.config.VIEW_OPTIONS = JSON.parse(so.result[0]);
    } else {
        Alert(Sepoa.cache.text.get('ECT_102.MESSAGE0002')); // 화면 설정 정보 로드에 실패하였습니다.
    }
}, false);


var result = true;
var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res, config, params) {
            if (!res.flag) {
                result = false;
                Alert(res.message);
            }
        }
    },
    contentType: "json",
    async: false
}

var params = $.extend(true, {
    module: "sepoa.svc.contract.SepoaEmployeeContractService",
    action: action
}, data);

sUtils.multipart.send(config, params);
return result;


const rId = tr.idd;
const row = gridObj.getRowDataObject(tr.idd);

const config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: (res, config, params) => {
            if(res.flag){
                const itemData = res.result[0];
                if(sUtils.string.isBlank(itemData) === false) {
                    for(const key in itemData){
                        const cId = 'EXT_' + key;
                        if(config.gridObj.columnIds.includes(cId)){
                            config.gridObj.setCellValue(config.TARGET_ROW_ID, cId, itemData[key]);
                        }
                    }
                }

                const signerList = res.result[1];
                if(sUtils.string.isBlank(signerList) === false) {
                    const targetSigner = signerList.find(e => e['SIGNER_ID'] == Sepoa.info.ID);
                    if(targetSigner) {
                        const signStatus = sUtils.cache.combo.get(`SL0003,${Sepoa.info.HOUSE_CODE}#${Sepoa.info.LANGUAGE}#CT002`);
                        const {text, value} = signStatus.find(e => e['value'] == targetSigner['SIGN_FLAG'])
                        if(text) {
                            const targetCell = gridObj.cells(rId, gridObj.getColIndexById('CONT_STATUS'));
                            targetCell.cell.textContent = text;
                        }
                    }
                }

                const historyList = res.result[2];
                if(sUtils.string.isBlank(historyList) === false) {
                    // 'SIGN_REQ_DATE' : 서명요청일
                    if(gridObj.columnIds.includes('SIGN_REQ_DATE')) {
                        const targetHistory = historyList.find(e => e['ACTION'] == 'SIGN_REQUEST');
                        if(targetHistory) {
                            config.gridObj.setCellValue(config.TARGET_ROW_ID, 'SIGN_REQ_DATE', targetHistory['ADD_DATE']);
                        }
                    }

                    // 'SIGN_FINISH_DATE' : 서명완료일
                    if(gridObj.columnIds.includes('SIGN_FINISH_DATE')) {
                        const targetHistory = historyList.find(e => e['ACTION'] == 'SIGN_COMPLETE');
                        if(targetHistory) {
                            config.gridObj.setCellValue(config.TARGET_ROW_ID, 'SIGN_FINISH_DATE', targetHistory['ADD_DATE']);
                        }
                    }
                }

                if(callback){
                    try{
                        callback(res, config, params);
                    }catch(e){
                        console.error(e);
                    }
                }
            }
        }
    },
    progress:false,
    gridObj:gridObj,
    TARGET_ROW_ID:rId
}

const params = {
    module: "sepoa.svc.contract.SepoaEmployeeContractService",
    action: "doDocumentExtra",
    CONT_NO: row['CONT_NO'],
    CONT_GL_SEQ: row['CONT_GL_SEQ'],
    CONT_TYPE : 'E'
};

if(['G'].includes(row['CONT_STATUS']) === false) {
    params['DISABLE_SELECT_SIGNER'] = true;
}

if(['G', 'A', 'C'].includes(row['CONT_STATUS']) === false) {
    params['DISABLE_SELECT_HISTORY'] = true;
}

sUtils.multipart.send(config, params);


if(data.DATA_SOURCE == "NEW"){
    callFunction('p', 'changeView', [{
        data: data,
        view: 'EDITOR'
    }]);
}else{
    const contStatus = data['CONT_STATUS'];
    const contMethod = data['CONT_METHOD'];
    const viewMap = {
        'T'     : 'EDITOR',
        'MF'    : 'EDITOR',
        'MW'    : 'EDITOR',
        'ALTER' : 'EDITOR',
        'RA'    : 'EDITOR',
        'RR'    : 'EDITOR',
        'I'     : 'APPROVAL',
        'R'     : 'APPROVAL',
        'RP'    : 'REVIEW',
        'A'     : 'COMPLETE',
        'X'     : 'TERMINATION',
        'K'     : 'TERMINATION',
        'EW'    : 'PREVIEW',
        'G'     : contMethod != 'S' ? 'SIGN' : 'EDITOR',
        'UW'    : contMethod == 'S' ? 'EDITOR' : 'VIEW',
    };

    let view = viewMap[contStatus] || 'VIEW';

    if(contStatus == 'T') {
        data = $.extend(true, { back: 'LIST' }, data);
    }

    callFunction('p', 'changeView', [{
        data: data,
        view: view
    }]);
}


if (dataArray.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
    return;
}
if (dataArray.length > 1) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006')); // 하나의 행만 선택해주세요.
    return;
}
for (var i in dataArray) {
    var contStatus = dataArray[i].CONT_STATUS;
    if (!['EW', 'EF', 'T'].includes(contStatus)) {
        Alert(Sepoa.cache.text.get('ECT_102.MESSAGE0003')); // 생성대기 상태에서만 삭제가 가능합니다.
        return;
    }
}

Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0008'), function(flag) {  // 선택한 계약서를 삭제하시겠습니까?
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback: function(res, config, params) {
                    if (!res.flag) {
                        Alert(ECT_102.MESSAGE0003);
                    } else {
                        Alert(Sepoa.cache.text.get('MESSAGE.0001')); // 성공적으로 처리되었습니다.
                        callback();
                    }
                }
            }
        }

        var params = {
            module: "sepoa.svc.contract.SepoaEmployeeContractService",
            action: "doDocumentDelete",
            CONT_NO: dataArray[0].CONT_NO,
            CONT_GL_SEQ: dataArray[0].CONT_GL_SEQ
        };
        sUtils.multipart.send(config, params);
    }
});


if (dataArray.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
    return; 
}
if (dataArray.length > 1) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006')); // 하나의 행만 선택해주세요.
    return;
}
for (var i in dataArray) {
    var contStatus = dataArray[i].CONT_STATUS;
    if (contStatus != 'A') {
        Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0007')); // 임시저장 상태에서만 가능합니다.
        return;
    }
}

Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0008'), function(flag) { // 선택한 계약서를 삭제하시겠습니까?
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback: function(res, config, params) {
                    if (!res.flag) {
                        Alert(res.message);
                    } else {
                        Alert(Sepoa.cache.text.get('MESSAGE.0001')); // 성공적으로 처리되었습니다.
                        callback();
                    }
                }
            }
        }

		var params = {
			module: "sepoa.svc.contract.SepoaEmployeeContractService",
            action: "doDocumentTermination",
            CONT_NO: dataArray[0].CONT_NO,
            CONT_GL_SEQ: dataArray[0].CONT_GL_SEQ,
            CONT_TYPE: dataArray[0].CONT_TYPE,
            T_MESSAGE: dataArray[0]['T_MESSAGE']
		}

		if(['S'].includes(dataArray[0].CONT_METHOD)){
			params.IS_FORCE = 'true';
		}

        sUtils.multipart.send(config, params);
    }
});


if (dataArray.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
    return;
}
if (dataArray.length > 1) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006')); // 하나의 행만 선택해주세요.
    return;
}
for (var i in dataArray) {
    var contStatus = dataArray[i].CONT_STATUS;
    if (contStatus != 'A') {
        Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0021')); // 계약완료 상태에서만 가능합니다.
        return;
    }
}

Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0023'), function(flag) { // 선택한 계약서를 변경하시겠습니까?
    if (flag) {
        if(dataArray[0].DATA_SOURCE == 'SRM'){
            //구매코드 호출
            dataArray[0].CONT_TYPE = 'ALTER'
            dataArray[0].CONT_STATUS = 'ALTER'
            doChangeView(dataArray[0]);
        }else{
            //내장코드 호출
            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res, config, params) {
                        if (!res.flag) {
                            Alert(res.message);
                        } else {
                            Alert(Sepoa.cache.text.get('MESSAGE.0001')); // 성공적으로 처리되었습니다.
                            callback();
                        }
                    }
                }
            }

            var params = {
                module: "sepoa.svc.contract.SepoaEmployeeContractService",
                action: "doDocumentAlteration",
                CONT_NO: dataArray[0].CONT_NO,
                CONT_GL_SEQ: dataArray[0].CONT_GL_SEQ
            };
            sUtils.multipart.send(config, params);
        }
    }
});


if (dataArray.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
    return;
}

var sendArray = [];
for (var i in dataArray) {
    var contStatus = dataArray[i].CONT_STATUS;
    if (contStatus != 'G') {
        Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0025')); // 서명 진행중인 건만 재전송 가능합니다.
        return;
    }
    sendArray.push({CONT_NO:dataArray[i].CONT_NO, CONT_GL_SEQ:dataArray[i].CONT_GL_SEQ, CONT_TYPE:dataArray[i].CONT_TYPE});
}

Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0026'), function(flag) { // 선택한 계약서를 재전송 하시겠습니까?
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback: function(res, config, params) {
                    if (!res.flag) {
                        Alert(res.message);
                    } else {
                        Alert(Sepoa.cache.text.get('MESSAGE.0001')); // 성공적으로 처리되었습니다.
                        callback();
                    }
                }
            },
            contentType:'json'
        }

        var params = {
            module: "sepoa.svc.contract.SepoaEmployeeContractService",
            action: "doPushResend",
            list:sendArray
        };
        sUtils.multipart.send(config, params);
    }
});


            if (dataArray.length == 0) {
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005')); // 선택된 행이 없습니다.
                return;
            }

            if (dataArray.length > 1) {
                Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006')); // 하나의 행만 선택해주세요.
                return;
            }

            var apStatus = dataArray[0].AP_STATUS;
            if (apStatus != 'F') {
				Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0030')); // 후속모듈이 실패한건만 재실행 가능합니다.
				return;
			}

            Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0031'), function(flag) { // 후속모듈을 재실행하시겠습니까?
                if (flag) {
                    var config = {
                        url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                        on: {
                            callback: function(res, config, params) {
                                if (!res.flag) {
                                    Alert(res.message);
                                } else {
                                    Alert(Sepoa.cache.text.get('MESSAGE.0001')); // 성공적으로 처리되었습니다.
                                    callback();
                                }
                            }
                        }
                    }

                    var params = {
                        module: "sepoa.svc.contract.SepoaEmployeeContractService",
                        action: "doAfterProcess",
                        CONT_NO: dataArray[0].CONT_NO,
                        CONT_GL_SEQ: dataArray[0].CONT_GL_SEQ
                    };
                    sUtils.multipart.send(config, params);
                }
            });


var config = {
    multiple:true,
    url:window.CONTEXT_NAME+'/SepoaActionController.sux',
    ext:['pdf','ppt','pptx','doc','docx','xls','xlsx','hwp','hwpx','jpg','png','jpeg','gif'],
    on:{
        callback:function(res, config, params){
        	if(res.flag) {
        		Alert(Sepoa.cache.text.get("POA_CONTRACT.MANUAL_COMPLETE_TITLE_COMMENT"), function() { // 수기계약서 업로드가 완료되었습니다
        			callFunction('p', 'changeView', [{view:'LIST'}])
        		});
        	} else {
        		Alert(res.message);
        		return;
        	}
        },
        beforeSend:function(config, params, files, idx){

        }
    }
}

var params = {
    module:"sepoa.svc.contract.SepoaEmployeeContractService",
    action: "doManualContractUpload",
    CONT_NO: data.CONT_NO,
    CONT_GL_SEQ: data.CONT_GL_SEQ
}

sUtils.multipart.upload(config, params);
